-- =============================================================================
-- AIGMS — 0047 — Couche outillage de l'éditeur
-- =============================================================================
-- GÉNÉRÉ par scripts/generate-tools-migration.mjs — ne pas éditer à la main.
-- Source : 01_Methodology/AIGMS_Outils_Controles_IT_IA.xlsx (v1.0), rattachements dans
-- knowledge/frameworks/aigms/tools/tool_control_map.json.
--
-- Un contrôle-type dit QUOI maîtriser ; un outil dit AVEC QUOI. Les 61
-- outils du classeur sont rattachés aux contrôles-types qu'ils instrumentent,
-- par code de contrôle — le lien survit aux versions du référentiel.
-- =============================================================================

insert into public.catalog_tool (
  tenant_id, code, phase, domain, acronym, tool_service, definition, tool_examples,
  controlled_object, control_question, expected_evidence, nature, automation,
  frequency, owner_role, risk_addressed, iso42001_refs, iso27001_refs,
  other_frameworks, priority, applicability, comments
)
select null, t.code, t.phase::app.aigms_phase, t.domain, t.acronym, t.tool_service, t.definition, t.tool_examples,
       t.controlled_object, t.control_question, t.expected_evidence, t.nature, t.automation,
       t.frequency, t.owner_role, t.risk_addressed, t.iso42001_refs, t.iso27001_refs,
       t.other_frameworks, t.priority, t.applicability, t.comments
from jsonb_to_recordset($tools$[{"code":"CTRL-INF-001","phase":"BUILD","domain":"Infrastructure cloud","acronym":"IaaS","tool_service":"Infrastructure as a Service","definition":"Fourniture de capacités de calcul, réseau et stockage virtualisées.","tool_examples":["Azure VM","AWS EC2","Google Compute Engine"],"controlled_object":"Hébergement des composants IA","control_question":"Les ressources IaaS supportant le système IA sont-elles inventoriées, approuvées, sécurisées et rattachées à un propriétaire ?","expected_evidence":["Inventaire cloud","tags","schéma d’architecture","revue de configuration"],"nature":"Préventif / Détectif","automation":"Semi-automatique","frequency":"Trimestrielle","owner_role":"Cloud Owner","risk_addressed":"Actifs inconnus, exposition ou responsabilités floues","iso42001_refs":["ISO/IEC 42001 : ressources, opérations, surveillance"],"iso27001_refs":["ISO/IEC 27001 : inventaire, configuration, sécurité cloud"],"other_frameworks":["AI Act : gestion des risques et traçabilité"],"priority":"Haute","applicability":"Selon architecture","comments":"","controls":["AIGMS-OPS-009","AIGMS-OPS-005"]},{"code":"CTRL-INF-002","phase":"BUILD","domain":"Infrastructure cloud","acronym":"PaaS","tool_service":"Platform as a Service","definition":"Services managés d’exécution, de données ou d’intégration.","tool_examples":["Azure App Service","Azure Functions","AWS Lambda","Google Cloud Run"],"controlled_object":"Plateformes managées utilisées par l’IA","control_question":"Les services PaaS utilisés sont-ils configurés selon une baseline approuvée, avec journalisation, chiffrement et restrictions réseau ?","expected_evidence":["Export de configuration","baseline","résultats CSPM","logs"],"nature":"Préventif / Détectif","automation":"Automatique","frequency":"Continue","owner_role":"Cloud Owner","risk_addressed":"Mauvaise configuration d’un service managé","iso42001_refs":["ISO/IEC 42001 : ressources et exploitation"],"iso27001_refs":["ISO/IEC 27001 : configuration, journalisation, réseau"],"other_frameworks":["NIST AI RMF : Govern / Manage"],"priority":"Haute","applicability":"Selon architecture","comments":"","controls":["AIGMS-OPS-005","AIGMS-SEC-001"]},{"code":"CTRL-INF-003","phase":"CONNECT","domain":"Services cloud","acronym":"SaaS","tool_service":"Software as a Service","definition":"Application fournie et exploitée par un tiers.","tool_examples":["Microsoft 365 Copilot","ChatGPT Enterprise","Salesforce Einstein"],"controlled_object":"Usage de services IA SaaS","control_question":"Chaque SaaS intégrant de l’IA fait-il l’objet d’une évaluation fournisseur, d’une configuration de sécurité et d’une validation des données autorisées ?","expected_evidence":["Registre fournisseurs","DPA","paramétrage tenant","analyse de risques"],"nature":"Préventif","automation":"Manuel","frequency":"Annuelle","owner_role":"Vendor Manager","risk_addressed":"Données exposées à un fournisseur non maîtrisé","iso42001_refs":["ISO/IEC 42001 : tiers et usage responsable"],"iso27001_refs":["ISO/IEC 27001 : fournisseurs et services cloud"],"other_frameworks":["AI Act : chaîne de valeur et transparence"],"priority":"Critique","applicability":"Toujours","comments":"","controls":["AIGMS-SUP-002","AIGMS-INV-001"]},{"code":"CTRL-INF-004","phase":"BUILD","domain":"Provisionnement","acronym":"IaC","tool_service":"Infrastructure as Code","definition":"Description versionnée et automatisée de l’infrastructure.","tool_examples":["Terraform","OpenTofu","Azure Bicep","CloudFormation"],"controlled_object":"Reproductibilité de l’environnement IA","control_question":"L’infrastructure du système IA est-elle définie par du code versionné, revue par un pair et testée avant déploiement ?","expected_evidence":["Dépôt IaC","pull requests","résultats de tests","historique pipeline"],"nature":"Préventif","automation":"Automatique","frequency":"À chaque changement","owner_role":"Cloud / DevOps","risk_addressed":"Dérive ou changement non autorisé","iso42001_refs":["ISO/IEC 42001 : opérations et maîtrise des changements"],"iso27001_refs":["ISO/IEC 27001 : gestion des configurations et changements"],"other_frameworks":["NIST AI RMF : Map / Manage"],"priority":"Haute","applicability":"Selon architecture","comments":"","controls":["AIGMS-OPS-005","AIGMS-OPS-007"]},{"code":"CTRL-INF-005","phase":"BUILD","domain":"Configuration","acronym":"CM","tool_service":"Configuration Management","definition":"Application cohérente de configurations sur les systèmes.","tool_examples":["Ansible","Puppet","Chef","Salt"],"controlled_object":"Baselines des actifs IA","control_question":"Une baseline documentée est-elle appliquée et les écarts de configuration sont-ils détectés et corrigés ?","expected_evidence":["Baseline","rapports de conformité","tickets de remédiation"],"nature":"Préventif / Détectif","automation":"Automatique","frequency":"Continue","owner_role":"Infrastructure Owner","risk_addressed":"Configuration incohérente ou affaiblie","iso42001_refs":["ISO/IEC 42001 : exploitation maîtrisée"],"iso27001_refs":["ISO/IEC 27001 : configuration sécurisée"],"other_frameworks":["NIST CSF : Protect"],"priority":"Haute","applicability":"Selon architecture","comments":"","controls":["AIGMS-OPS-005"]},{"code":"CTRL-DEV-001","phase":"BUILD","domain":"Gestion de code","acronym":"SCM / Git","tool_service":"Source Code Management","definition":"Versionnement du code, des configurations et de certains artefacts IA.","tool_examples":["GitHub","GitLab","Azure Repos","Bitbucket"],"controlled_object":"Code et configuration du système IA","control_question":"Les dépôts sont-ils privés si nécessaire, protégés par branches, revues, signatures et séparation des rôles ?","expected_evidence":["Paramètres du dépôt","règles de branche","journal des revues"],"nature":"Préventif","automation":"Semi-automatique","frequency":"À chaque changement","owner_role":"Engineering Manager","risk_addressed":"Modification non autorisée ou non traçable","iso42001_refs":["ISO/IEC 42001 : cycle de vie et responsabilités"],"iso27001_refs":["ISO/IEC 27001 : développement sécurisé et contrôle d’accès"],"other_frameworks":["AI Act : documentation et traçabilité"],"priority":"Haute","applicability":"Toujours","comments":"","controls":["AIGMS-OPS-004","AIGMS-OPS-005"]},{"code":"CTRL-DEV-002","phase":"BUILD","domain":"Déploiement","acronym":"CI/CD","tool_service":"Continuous Integration / Continuous Delivery","definition":"Pipeline automatisé de construction, tests, approbation et déploiement.","tool_examples":["GitHub Actions","GitLab CI","Azure Pipelines","Jenkins"],"controlled_object":"Mise en production des composants IA","control_question":"Le pipeline impose-t-il tests, analyses de sécurité, évaluations IA et approbation avant production ?","expected_evidence":["Définition pipeline","journaux","approbations","résultats d’évaluation"],"nature":"Préventif","automation":"Automatique","frequency":"À chaque version","owner_role":"DevOps / Model Owner","risk_addressed":"Version non testée ou non approuvée en production","iso42001_refs":["ISO/IEC 42001 : cycle de vie et exploitation"],"iso27001_refs":["ISO/IEC 27001 : changements et développement sécurisé"],"other_frameworks":["AI Act : précision, robustesse, traçabilité"],"priority":"Critique","applicability":"Toujours","comments":"","controls":["AIGMS-OPS-001","AIGMS-SEC-012"]},{"code":"CTRL-DEV-003","phase":"BUILD","domain":"Artefacts","acronym":"Repository","tool_service":"Artifact Repository","definition":"Stockage contrôlé des packages, images et livrables.","tool_examples":["Azure Artifacts","JFrog Artifactory","Nexus","GHCR"],"controlled_object":"Intégrité des livrables IA","control_question":"Les artefacts déployables sont-ils immuables, signés, scannés et rattachés à une version source ?","expected_evidence":["Hash","signature","provenance build","rapport de scan"],"nature":"Préventif","automation":"Automatique","frequency":"À chaque version","owner_role":"DevOps","risk_addressed":"Substitution ou altération d’un artefact","iso42001_refs":["ISO/IEC 42001 : intégrité du cycle de vie"],"iso27001_refs":["ISO/IEC 27001 : intégrité et développement sécurisé"],"other_frameworks":["SLSA / supply chain logicielle"],"priority":"Haute","applicability":"Selon architecture","comments":"","controls":["AIGMS-OPS-003","AIGMS-OPS-007"]},{"code":"CTRL-DEV-004","phase":"BUILD","domain":"Conteneurs","acronym":"Docker","tool_service":"Conteneurisation","definition":"Empaquetage reproductible d’une application et de ses dépendances.","tool_examples":["Docker","Podman"],"controlled_object":"Images des services IA","control_question":"Les images sont-elles minimales, sans secrets, exécutées sans privilèges et régulièrement reconstruites ?","expected_evidence":["Dockerfile","scan d’image","paramètres runtime","SBOM"],"nature":"Préventif / Détectif","automation":"Automatique","frequency":"À chaque version","owner_role":"Platform Engineer","risk_addressed":"Vulnérabilité ou privilège excessif dans l’image","iso42001_refs":["ISO/IEC 42001 : ressources techniques"],"iso27001_refs":["ISO/IEC 27001 : développement sécurisé et vulnérabilités"],"other_frameworks":["NIST SSDF"],"priority":"Haute","applicability":"Selon architecture","comments":"","controls":["AIGMS-SEC-004","AIGMS-SEC-003"]},{"code":"CTRL-DEV-005","phase":"OPERATE","domain":"Orchestration","acronym":"K8s","tool_service":"Kubernetes","definition":"Orchestration de conteneurs, services, secrets et politiques réseau.","tool_examples":["AKS","EKS","GKE","OpenShift"],"controlled_object":"Workloads IA conteneurisés","control_question":"Les workloads IA sont-ils isolés par namespace, soumis à des politiques réseau et exécutés avec des identités minimales ?","expected_evidence":["Manifests","RBAC","NetworkPolicy","admission policies","audit logs"],"nature":"Préventif / Détectif","automation":"Automatique","frequency":"Continue","owner_role":"Platform Owner","risk_addressed":"Mouvement latéral, fuite ou privilèges excessifs","iso42001_refs":["ISO/IEC 42001 : exploitation et sécurité des ressources"],"iso27001_refs":["ISO/IEC 27001 : accès, réseau, journalisation"],"other_frameworks":["NIST CSF : Protect / Detect"],"priority":"Critique","applicability":"Selon architecture","comments":"","controls":["AIGMS-SEC-003","AIGMS-OPS-002"]},{"code":"CTRL-OPS-001","phase":"OPERATE","domain":"Exploitation distante","acronym":"RMM","tool_service":"Remote Monitoring & Management","definition":"Supervision et administration à distance des postes, serveurs et agents.","tool_examples":["NinjaOne","N-able","Datto RMM","ConnectWise","Atera","Kaseya VSA"],"controlled_object":"Parc supportant ou accédant à l’IA","control_question":"Le RMM couvre-t-il tous les actifs concernés, remonte-t-il les alertes critiques et applique-t-il les correctifs selon les SLA ?","expected_evidence":["Couverture agents","rapport patching","alertes","tickets","SLA"],"nature":"Détectif / Correctif","automation":"Automatique","frequency":"Continue","owner_role":"IT Operations / MSP","risk_addressed":"Actif non supervisé, obsolète ou compromis","iso42001_refs":["ISO/IEC 42001 : surveillance opérationnelle"],"iso27001_refs":["ISO/IEC 27001 : vulnérabilités, journalisation, capacité"],"other_frameworks":["NIST CSF : Detect / Respond"],"priority":"Critique","applicability":"Selon parc","comments":"Evidence Provider majeur pour AIGMS","controls":["AIGMS-OPS-008","AIGMS-MON-005"]},{"code":"CTRL-OPS-002","phase":"OPERATE","domain":"Gestion des services","acronym":"ITSM","tool_service":"IT Service Management","definition":"Gestion structurée des incidents, problèmes, demandes et changements.","tool_examples":["ServiceNow","Jira Service Management","Freshservice","GLPI"],"controlled_object":"Incidents et changements affectant l’IA","control_question":"Les incidents, problèmes et changements liés aux systèmes IA sont-ils identifiés comme tels, priorisés et reliés aux actifs concernés ?","expected_evidence":["Tickets","catégories IA","SLA","post-mortems","changements"],"nature":"Détectif / Correctif","automation":"Semi-automatique","frequency":"Continue","owner_role":"Service Manager","risk_addressed":"Incident IA perdu dans le flux IT général","iso42001_refs":["ISO/IEC 42001 : incidents, amélioration et opérations"],"iso27001_refs":["ISO/IEC 27001 : incidents et changements"],"other_frameworks":["AI Act : surveillance après déploiement"],"priority":"Critique","applicability":"Toujours","comments":"","controls":["AIGMS-INC-002","AIGMS-OPS-006"]},{"code":"CTRL-OPS-003","phase":"OPERATE","domain":"Configuration","acronym":"CMDB","tool_service":"Configuration Management Database","definition":"Référentiel des actifs et de leurs dépendances.","tool_examples":["ServiceNow CMDB","Device42","GLPI","iTop"],"controlled_object":"Chaîne processus–use case–actifs","control_question":"Chaque cas d’usage IA est-il relié dans la CMDB aux applications, API, données, modèles, infrastructures et propriétaires ?","expected_evidence":["Fiches CI","relations","taux de complétude","revues de propriété"],"nature":"Préventif / Détectif","automation":"Semi-automatique","frequency":"Mensuelle","owner_role":"Configuration Manager","risk_addressed":"Dépendances et impacts inconnus","iso42001_refs":["ISO/IEC 42001 : inventaire et responsabilités"],"iso27001_refs":["ISO/IEC 27001 : inventaire des actifs"],"other_frameworks":["NIST AI RMF : Map"],"priority":"Critique","applicability":"Toujours","comments":"","controls":["AIGMS-INV-007","AIGMS-OPS-005"]},{"code":"CTRL-OPS-004","phase":"OPERATE","domain":"Terminaux","acronym":"UEM / MDM","tool_service":"Unified Endpoint Management / Mobile Device Management","definition":"Administration des postes, mobiles et politiques de conformité.","tool_examples":["Microsoft Intune","Workspace ONE","Jamf","Ivanti"],"controlled_object":"Terminaux accédant aux services IA","control_question":"L’accès aux services IA sensibles est-il limité aux terminaux gérés, conformes, chiffrés et à jour ?","expected_evidence":["Politiques de conformité","inventaire","Conditional Access","rapports"],"nature":"Préventif","automation":"Automatique","frequency":"Continue","owner_role":"Endpoint Owner","risk_addressed":"Exfiltration depuis un terminal non maîtrisé","iso42001_refs":["ISO/IEC 42001 : sécurité des ressources"],"iso27001_refs":["ISO/IEC 27001 : terminaux et accès"],"other_frameworks":["NIST CSF : Protect"],"priority":"Haute","applicability":"Selon usages","comments":"","controls":["AIGMS-SEC-002","AIGMS-SEC-003"]},{"code":"CTRL-OPS-005","phase":"OPERATE","domain":"Réseau","acronym":"NMS","tool_service":"Network Management System","definition":"Supervision des équipements, liens et performances réseau.","tool_examples":["SolarWinds","PRTG","Zabbix","LibreNMS"],"controlled_object":"Réseau desservant les services IA","control_question":"Les équipements et liens critiques pour l’IA sont-ils supervisés avec seuils, escalade et capacité suffisante ?","expected_evidence":["Cartographie réseau","alertes","historique disponibilité","capacité"],"nature":"Détectif","automation":"Automatique","frequency":"Continue","owner_role":"Network Owner","risk_addressed":"Indisponibilité ou dégradation des services IA","iso42001_refs":["ISO/IEC 42001 : continuité et surveillance"],"iso27001_refs":["ISO/IEC 27001 : réseau, capacité, continuité"],"other_frameworks":["NIST CSF : Detect / Recover"],"priority":"Moyenne","applicability":"Selon architecture","comments":"","controls":["AIGMS-OPS-010","AIGMS-MON-005"]},{"code":"CTRL-OPS-006","phase":"OPERATE","domain":"Supervision infrastructure","acronym":"Monitoring","tool_service":"Infrastructure Monitoring","definition":"Mesure de disponibilité, CPU, mémoire, disque et ressources.","tool_examples":["Azure Monitor","AWS CloudWatch","Prometheus","Zabbix"],"controlled_object":"Capacité et disponibilité IA","control_question":"Les métriques critiques sont-elles définies, assorties de seuils, de responsables et de procédures de réaction ?","expected_evidence":["Dashboards","règles d’alerte","astreinte","historique SLO"],"nature":"Détectif","automation":"Automatique","frequency":"Continue","owner_role":"SRE / Operations","risk_addressed":"Saturation ou indisponibilité non détectée","iso42001_refs":["ISO/IEC 42001 : surveillance, mesure et exploitation"],"iso27001_refs":["ISO/IEC 27001 : capacité, journalisation, continuité"],"other_frameworks":["NIST AI RMF : Measure / Manage"],"priority":"Haute","applicability":"Toujours","comments":"","controls":["AIGMS-MON-005","AIGMS-MON-001"]},{"code":"CTRL-OPS-007","phase":"OPERATE","domain":"Performance applicative","acronym":"APM","tool_service":"Application Performance Monitoring","definition":"Suivi des performances, erreurs et dépendances applicatives.","tool_examples":["Datadog","Dynatrace","New Relic","Application Insights"],"controlled_object":"Applications et API IA","control_question":"L’APM permet-il de détecter les erreurs, latences et dépendances dégradées d’un parcours IA de bout en bout ?","expected_evidence":["Traces APM","SLO","alertes","rapports d’incident"],"nature":"Détectif","automation":"Automatique","frequency":"Continue","owner_role":"Application Owner / SRE","risk_addressed":"Dégradation silencieuse de la qualité de service","iso42001_refs":["ISO/IEC 42001 : surveillance opérationnelle"],"iso27001_refs":["ISO/IEC 27001 : surveillance et capacité"],"other_frameworks":["NIST AI RMF : Measure"],"priority":"Haute","applicability":"Toujours","comments":"","controls":["AIGMS-MON-005"]},{"code":"CTRL-OBS-001","phase":"OPERATE","domain":"Observabilité","acronym":"Logs","tool_service":"Journaux d’événements","definition":"Enregistrement horodaté des actions et événements.","tool_examples":["Elastic","Loki","Azure Log Analytics","Splunk"],"controlled_object":"Traçabilité des usages et opérations IA","control_question":"Les événements nécessaires à l’audit d’un système IA sont-ils définis, horodatés, protégés, conservés et consultables ?","expected_evidence":["Politique de logs","exemples","rétention","contrôle d’intégrité"],"nature":"Détectif","automation":"Automatique","frequency":"Continue","owner_role":"Security / Platform Owner","risk_addressed":"Absence de preuve ou d’investigation possible","iso42001_refs":["ISO/IEC 42001 : traçabilité et surveillance"],"iso27001_refs":["ISO/IEC 27001 : journalisation et monitoring"],"other_frameworks":["AI Act : conservation des journaux"],"priority":"Critique","applicability":"Toujours","comments":"Éviter de journaliser inutilement prompts et données sensibles","controls":["AIGMS-SEC-006","AIGMS-INC-006"]},{"code":"CTRL-OBS-002","phase":"OPERATE","domain":"Observabilité","acronym":"Metrics","tool_service":"Métriques","definition":"Mesures numériques de volume, latence, coût, qualité et erreurs.","tool_examples":["Prometheus","Grafana","Datadog","Azure Monitor"],"controlled_object":"Performance et comportement IA","control_question":"Les métriques techniques, qualité IA, sécurité et coûts sont-elles reliées à des seuils et objectifs approuvés ?","expected_evidence":["Catalogue de métriques","dashboard","seuils","SLO/KPI"],"nature":"Détectif","automation":"Automatique","frequency":"Continue","owner_role":"AI System Owner","risk_addressed":"Dérive ou dégradation non quantifiée","iso42001_refs":["ISO/IEC 42001 : objectifs et mesure"],"iso27001_refs":["ISO/IEC 27001 : monitoring et capacité"],"other_frameworks":["NIST AI RMF : Measure"],"priority":"Haute","applicability":"Toujours","comments":"","controls":["AIGMS-MON-001","AIGMS-MON-006"]},{"code":"CTRL-OBS-003","phase":"OPERATE","domain":"Observabilité","acronym":"Traces","tool_service":"Traçage distribué","definition":"Suivi d’une transaction à travers ses composants.","tool_examples":["OpenTelemetry","Jaeger","Tempo","Application Insights"],"controlled_object":"Chaîne application–RAG–LLM–outil","control_question":"Une requête peut-elle être retracée de bout en bout sans exposer de données interdites ?","expected_evidence":["Trace ID","spans","politique de masquage","exemple d’investigation"],"nature":"Détectif","automation":"Automatique","frequency":"Continue","owner_role":"Platform / AI Engineer","risk_addressed":"Impossibilité d’identifier l’origine d’une sortie ou erreur","iso42001_refs":["ISO/IEC 42001 : traçabilité et opérations"],"iso27001_refs":["ISO/IEC 27001 : journalisation, protection des données"],"other_frameworks":["AI Act : traçabilité"],"priority":"Haute","applicability":"Selon architecture","comments":"","controls":["AIGMS-SEC-006","AIGMS-DAT-009"]},{"code":"CTRL-OBS-004","phase":"BUILD","domain":"Instrumentation","acronym":"OTel","tool_service":"OpenTelemetry","definition":"Standard ouvert d’instrumentation des logs, métriques et traces.","tool_examples":["OpenTelemetry SDK","Collector"],"controlled_object":"Normalisation des preuves techniques","control_question":"L’instrumentation couvre-t-elle les composants critiques avec corrélation, filtrage des données et export vers des destinations approuvées ?","expected_evidence":["Configuration OTel","schéma des flux","tests de couverture"],"nature":"Préventif / Détectif","automation":"Automatique","frequency":"À chaque version","owner_role":"Observability Owner","risk_addressed":"Télémétrie incomplète ou contenant des données sensibles","iso42001_refs":["ISO/IEC 42001 : surveillance et mesure"],"iso27001_refs":["ISO/IEC 27001 : journalisation et transfert"],"other_frameworks":["NIST AI RMF : Measure"],"priority":"Moyenne","applicability":"Selon architecture","comments":"","controls":["AIGMS-SEC-006","AIGMS-MON-005"]},{"code":"CTRL-RES-001","phase":"OPERATE","domain":"Résilience","acronym":"Backup / DR","tool_service":"Sauvegarde et reprise d’activité","definition":"Protection et restauration des configurations, données et services.","tool_examples":["Azure Backup","Veeam","AWS Backup","Velero"],"controlled_object":"Continuité du système IA","control_question":"Les éléments nécessaires à la reprise du système IA sont-ils sauve